export default [["q-fcps-pat4-01","A child has recurrent bacterial infections, delayed umbilical cord separation and marked neutrophilia without pus formation. The defect is in:",["CD18 integrin (leukocyte adhesion)","NADPH oxidase","Myeloperoxidase","Lysosomal trafficking regulator"],"Leukocyte adhesion deficiency type 1 is absent beta-2 integrin, so neutrophils cannot adhere and emigrate and stay in the blood."],["q-fcps-pat4-02","Which complement component deficiency predisposes to recurrent Neisseria infections?",["Terminal components C5 to C9","C1 esterase inhibitor","C3","Decay-accelerating factor"],"The membrane attack complex is needed to lyse Neisseria, so deficiency gives recurrent meningococcal and gonococcal infection."],["q-fcps-pat4-03","Hereditary angioedema is caused by deficiency of:",["C1 esterase inhibitor","C3","C5","Factor H"],"Uncontrolled bradykinin production causes swelling without urticaria, and C4 is low."],["q-fcps-pat4-04","Which cell type is the main source of granulation tissue collagen in wound healing?",["Fibroblasts","Macrophages","Neutrophils","Mast cells"],"Fibroblasts lay down type III collagen first, which is later replaced by type I during remodelling."],["q-fcps-pat4-05","Which collagen type is deposited first in a healing wound?",["Type III","Type I","Type II","Type IV"],"Early granulation tissue contains type III collagen, and it is replaced by stronger type I collagen over weeks."],["q-fcps-pat4-06","A patient has a sudden onset of dyspnoea, petechiae and confusion 48 hours after a femur fracture. The most likely diagnosis is:",["Fat embolism","Pulmonary thromboembolism","Air embolism","Amniotic fluid embolism"],"Fat embolism syndrome presents classically 24 to 72 hours after long bone fracture with respiratory failure, neurological signs and petechiae."],["q-fcps-pat4-07","A woman collapses during labour and develops hypoxia and disseminated intravascular coagulation. Which condition is likely?",["Amniotic fluid embolism","Pulmonary thromboembolism","Septic shock","Fat embolism"],"Fetal squamous cells and mucin enter the maternal circulation and trigger an anaphylactoid reaction with DIC."],["q-fcps-pat4-08","A paradoxical embolus passes from a leg vein to the brain through a:",["Patent foramen ovale","Patent ductus arteriosus only","Mitral stenosis","Pulmonary shunt"],"A right-to-left shunt allows a venous thrombus to enter the systemic arterial circulation and cause a stroke."],["q-fcps-pat4-09","In the stages of shock, which finding is characteristic of the initial non-progressive stage?",["Compensatory tachycardia and vasoconstriction","Irreversible cell damage","Anuria","Metabolic acidosis with multiorgan failure"],"In the early compensated stage, reflex mechanisms maintain perfusion of vital organs."],["q-fcps-pat4-10","Which tumour suppressor gene is mutated in familial adenomatous polyposis?",["APC","RB","p53","NF1"],"APC mutations activate the Wnt pathway, producing hundreds of colorectal polyps with nearly 100 percent progression to cancer."],["q-fcps-pat4-11","Which oncogene is amplified in some breast cancers and is the target of trastuzumab?",["HER2 (ERBB2)","MYC","RAS","BCL2"],"HER2 amplification gives a more aggressive tumour that responds to trastuzumab."],["q-fcps-pat4-12","Burkitt lymphoma involves overexpression of which gene?",["MYC","BCL2","Cyclin D1","RAS"],"The t(8;14) translocation places MYC under the immunoglobulin heavy chain promoter."],["q-fcps-pat4-13","Follicular lymphoma is characterised by which translocation?",["t(14;18) with BCL2 overexpression","t(8;14)","t(11;14)","t(9;22)"],"BCL2 overexpression blocks apoptosis, causing an indolent lymphoma of germinal centre B cells."],["q-fcps-pat4-14","Mantle cell lymphoma is associated with:",["t(11;14) and cyclin D1 overexpression","t(14;18)","t(8;14)","t(15;17)"],"Cyclin D1 overexpression drives progression through the G1-S checkpoint."],["q-fcps-pat4-15","Acute promyelocytic leukaemia is characterised by:",["t(15;17) and Auer rods, with a risk of DIC","t(9;22) and basophilia","t(8;21) only","Smudge cells"],"The PML-RARA fusion blocks differentiation, and treatment with all-trans retinoic acid induces maturation."],["q-fcps-pat4-16","Which neoplasm is associated with the JAK2 V617F mutation?",["Polycythaemia vera","Chronic myeloid leukaemia","Hairy cell leukaemia","Multiple myeloma"],"JAK2 V617F is found in most polycythaemia vera and in many cases of essential thrombocythaemia and primary myelofibrosis."],["q-fcps-pat4-17","Which tumour marker is used to monitor ovarian epithelial cancer?",["CA-125","CA 19-9","CEA","PSA"],"CA-125 is raised in epithelial ovarian cancer but is not specific because it can rise in endometriosis and menstruation."],["q-fcps-pat4-18","Which tumour marker is used to follow colorectal cancer recurrence?",["CEA","AFP","CA-125","Calcitonin"],"Carcinoembryonic antigen is used mainly for monitoring after resection rather than for screening."],["q-fcps-pat4-19","A man with a testicular mass has a markedly raised beta-hCG and a normal AFP. The tumour is most likely:",["Choriocarcinoma","Yolk sac tumour","Mature teratoma","Leydig cell tumour"],"Choriocarcinoma gives very high beta-hCG, while yolk sac tumours produce AFP. Pure seminomas may produce only mildly raised hCG."],["q-fcps-pat4-20","Which paraneoplastic syndrome is characteristic of squamous cell carcinoma of the lung?",["Hypercalcaemia from PTHrP","SIADH","Cushing syndrome","Lambert-Eaton syndrome"],"Squamous cancers secrete PTH-related peptide. Small cell cancers secrete ADH and ACTH."],["q-fcps-pat4-21","Which carcinogen is most strongly associated with mesothelioma?",["Asbestos","Silica","Coal dust","Beryllium"],"Asbestos exposure causes pleural plaques, asbestosis, lung carcinoma and malignant mesothelioma after a latent period of decades."],["q-fcps-pat4-22","Aromatic amines such as aniline dyes cause which cancer?",["Urothelial (bladder) carcinoma","Hepatic angiosarcoma","Lung adenocarcinoma","Nasal adenocarcinoma"],"Occupational exposure in dye and rubber workers is a classic cause of bladder carcinoma, as is smoking."],["q-fcps-pat4-23","Vinyl chloride exposure is associated with:",["Hepatic angiosarcoma","Mesothelioma","Cholangiocarcinoma","Bladder carcinoma"],"Angiosarcoma of the liver is a rare tumour linked to vinyl chloride, arsenic and thorotrast."],["q-fcps-pat4-24","The oncogenic action of high-risk human papillomavirus involves:",["E6 degrading p53 and E7 inactivating RB","Insertion of the virus near MYC","Activating RAS","Blocking BCL2"],"E6 promotes degradation of p53 and E7 binds RB, allowing the cell to cycle unchecked, which leads to cervical intraepithelial neoplasia."],["q-fcps-pat4-25","Epstein-Barr virus is associated with all of the following EXCEPT:",["Hepatocellular carcinoma","Nasopharyngeal carcinoma","Burkitt lymphoma","Post-transplant lymphoproliferative disease"],"Hepatocellular carcinoma is linked to hepatitis B and C and aflatoxin, not EBV."],["q-fcps-pat4-26","Gastric MALT lymphoma may regress after treatment of:",["Helicobacter pylori","Hepatitis C","Epstein-Barr virus","Cytomegalovirus"],"Chronic H. pylori infection drives B cell proliferation, and eradication often induces remission in early disease."],["q-fcps-pat4-27","HLA-B27 is associated with:",["Ankylosing spondylitis","Rheumatoid arthritis","Type 1 diabetes","Multiple sclerosis"],"HLA-B27 is associated with the seronegative spondyloarthropathies, including reactive arthritis and psoriatic arthritis."],["q-fcps-pat4-28","HLA-DR3 and DR4 are associated with:",["Type 1 diabetes mellitus","Ankylosing spondylitis","Goodpasture syndrome","Narcolepsy"],"Both haplotypes increase risk of autoimmune destruction of pancreatic beta cells."],["q-fcps-pat4-29","Hyperacute rejection of a transplanted kidney is mediated by:",["Preformed antibodies against donor antigens","Sensitised T cells","Immune complex deposition after months","Chronic vascular intimal thickening"],"Preformed anti-ABO or anti-HLA antibodies cause thrombotic occlusion of the graft vessels within minutes to hours."],["q-fcps-pat4-30","Chronic rejection of a kidney graft is characterised by:",["Concentric intimal fibrosis of graft arteries","Neutrophilic infiltration of the vessels","Thrombosis within hours","Cellular infiltrate with tubulitis only"],"Chronic allograft vasculopathy leads to gradual graft failure over months to years."],["q-fcps-pat4-31","Which type of amyloid is associated with long-standing rheumatoid arthritis and tuberculosis?",["AA amyloid derived from serum amyloid A","AL amyloid","Abeta amyloid","Beta-2 microglobulin amyloid"],"Secondary (reactive) amyloidosis arises from chronic inflammation and mainly affects the kidney, liver and spleen."],["q-fcps-pat4-32","AL amyloid is derived from:",["Immunoglobulin light chains","Serum amyloid A","Transthyretin","Calcitonin"],"Primary amyloidosis occurs in plasma cell dyscrasias such as multiple myeloma and affects the heart, kidney and tongue."],["q-fcps-pat4-33","A boy has recurrent bacterial infections from the age of 6 months with absent B cells and very low immunoglobulins of all classes. The mutation is in:",["Bruton tyrosine kinase","ADA","CD40 ligand","WAS protein"],"X-linked agammaglobulinaemia from BTK defects blocks B cell maturation, so the tonsils are small and patients have recurrent sinopulmonary infections."],["q-fcps-pat4-34","A boy with eczema, thrombocytopenia with small platelets and recurrent infections has:",["Wiskott-Aldrich syndrome","Bruton agammaglobulinaemia","DiGeorge syndrome","Hyper-IgM syndrome"],"It is an X-linked disorder of the WAS gene affecting cytoskeletal function of haematopoietic cells."],["q-fcps-pat4-35","A patient has HIV infection and a CD4 count of 80 per microlitre. Which infection is most likely to cause cerebral ring-enhancing lesions?",["Toxoplasma gondii","Cryptococcus neoformans","Cytomegalovirus","Mycobacterium avium complex"],"Reactivation of Toxoplasma cysts causes multiple ring-enhancing lesions in advanced HIV disease."],["q-fcps-pat4-36","Which karyotype is typical of Klinefelter syndrome?",["47,XXY","45,X","47,XYY","47,XXX"],"Klinefelter syndrome presents with tall stature, small firm testes, gynaecomastia and infertility."],["q-fcps-pat4-37","Turner syndrome is associated with:",["Coarctation of the aorta and streak ovaries","Pulmonary stenosis only","Tall stature","Elevated oestrogen"],"Patients with 45,X have short stature, webbed neck, primary amenorrhoea with raised FSH and bicuspid aortic valve."],["q-fcps-pat4-38","Down syndrome most commonly results from:",["Meiotic nondisjunction of chromosome 21","Robertsonian translocation in most cases","Mosaicism","Deletion of 21q"],"About 95 percent are caused by nondisjunction, and the risk rises with maternal age."],["q-fcps-pat4-39","A tall man with arachnodactyly and aortic root dilatation has a defect in:",["Fibrillin-1","Type I collagen","Type III collagen","Elastin"],"Marfan syndrome results from FBN1 mutation with excess TGF-beta signalling. Complications include aortic dissection and ectopia lentis."],["q-fcps-pat4-40","Hereditary spherocytosis is best diagnosed by:",["Increased osmotic fragility with a negative direct Coombs test","Heinz bodies","Positive direct Coombs test","Ham test"],"Defects of spectrin or ankyrin make red cells spherical, so they are removed in the spleen. The Coombs test is negative."],["q-fcps-pat4-41","Heinz bodies and bite cells are seen in:",["G6PD deficiency","Hereditary spherocytosis","Sickle cell disease","Thalassaemia"],"Oxidative stress denatures haemoglobin, producing Heinz bodies, which the spleen removes as bite cells."],["q-fcps-pat4-42","Warm autoimmune haemolytic anaemia is typically mediated by:",["IgG antibodies","IgM antibodies","Cold agglutinins","Complement alone"],"IgG-coated red cells are cleared in the spleen. Cold agglutinin disease is IgM-mediated, with intravascular haemolysis in the cold."],["q-fcps-pat4-43","Paroxysmal nocturnal haemoglobinuria is caused by deficiency of:",["GPI-anchored proteins CD55 and CD59","Ankyrin","Spectrin","Glucose-6-phosphate dehydrogenase"],"PIGA mutation leads to complement-mediated lysis of red cells and a risk of venous thrombosis."],["q-fcps-pat4-44","Which finding is typical of aplastic anaemia?",["Pancytopenia with a hypocellular bone marrow","Pancytopenia with a hypercellular marrow","Isolated anaemia with reticulocytosis","Blasts in the blood"],"The marrow is replaced by fat. Causes include drugs, viral infections and idiopathic autoimmune destruction."],["q-fcps-pat4-45","Thrombotic thrombocytopenic purpura is caused by deficiency of:",["ADAMTS13","Factor VIII","von Willebrand factor","Glycoprotein Ib"],"Loss of ADAMTS13 leaves ultra-large von Willebrand multimers, so platelets aggregate in small vessels, causing microangiopathic haemolysis."],["q-fcps-pat4-46","Which laboratory finding is typical of von Willebrand disease?",["Prolonged bleeding time with normal platelet count","Low platelet count","Prolonged prothrombin time","Low fibrinogen"],"Defective platelet adhesion and secondary low factor VIII can prolong the aPTT, while the PT is normal."],["q-fcps-pat4-47","Which finding is characteristic of hypertrophic cardiomyopathy?",["Myocyte disarray with asymmetric septal hypertrophy","Dilated ventricles","Amyloid deposits","Granulomas"],"It is caused by sarcomere gene mutations such as beta-myosin heavy chain and is a leading cause of sudden death in young athletes."],["q-fcps-pat4-48","Silicosis predisposes to which infection?",["Tuberculosis","Aspergillosis","Legionella","Pneumocystis"],"Silica impairs macrophage function and increases the risk of tuberculosis. Eggshell calcification of hilar nodes is typical."],["q-fcps-pat4-49","Ferruginous bodies in the lung are characteristic of:",["Asbestosis","Silicosis","Coal workers' pneumoconiosis","Berylliosis"],"Asbestos fibres coated with haemosiderin appear as golden-brown beaded rods in lung tissue."],["q-fcps-pat4-50","Non-caseating granulomas with raised serum ACE and bilateral hilar lymphadenopathy in a young woman suggest:",["Sarcoidosis","Tuberculosis","Hodgkin lymphoma","Histoplasmosis"],"Sarcoidosis is a multisystem granulomatous disease that may cause hypercalcaemia through vitamin D activation."],["q-fcps-pat4-51","Hyaline membranes lining alveoli are typical of:",["Diffuse alveolar damage (ARDS)","Chronic bronchitis","Bronchiectasis","Asthma"],"Acute respiratory distress syndrome shows diffuse alveolar damage, with endothelial and epithelial injury and protein-rich exudate."],["q-fcps-pat4-52","Chronic bronchitis is defined clinically by cough with sputum for at least:",["3 months in each of 2 consecutive years","1 month in a year","6 weeks in total","1 year without remission"],"Pathology shows mucous gland hypertrophy, with an increased Reid index above 0.4."],["q-fcps-pat4-53","Skip lesions, cobblestone mucosa and a fistula in a patient with diarrhoea suggest:",["Crohn disease","Ulcerative colitis","Ischaemic colitis","Coeliac disease"],"Crohn disease is transmural and can affect any part of the gut, and it is associated with strictures and fistulae."],["q-fcps-pat4-54","Which feature favours ulcerative colitis over Crohn disease?",["Continuous mucosal inflammation starting in the rectum","Transmural inflammation","Non-caseating granulomas","Skip lesions"],"Ulcerative colitis is limited to the mucosa and submucosa, with crypt abscesses and a risk of toxic megacolon and primary sclerosing cholangitis."],["q-fcps-pat4-55","Which hepatitis virus is transmitted by the faecal-oral route and is particularly dangerous in pregnancy?",["Hepatitis E","Hepatitis B","Hepatitis C","Hepatitis D"],"Hepatitis E causes high mortality from fulminant hepatic failure in pregnant women, especially in the third trimester."],["q-fcps-pat4-56","Which hepatitis serological pattern indicates a vaccinated person?",["Anti-HBs positive only","HBsAg and anti-HBc positive","Anti-HBc IgM positive","HBeAg positive"],"Vaccination produces antibody to surface antigen alone, while natural infection also produces anti-HBc."],["q-fcps-pat4-57","A patient with chronic hepatitis B has a rising AFP and a liver mass. The most likely diagnosis is:",["Hepatocellular carcinoma","Cholangiocarcinoma","Haemangioma","Focal nodular hyperplasia"],"Cirrhosis from chronic hepatitis B or C is the main risk factor, though HBV can cause HCC without cirrhosis."],["q-fcps-pat4-58","In acute pancreatitis, which two causes are most common?",["Gallstones and alcohol","Hypertriglyceridaemia and trauma","Drugs and viral infection","ERCP and scorpion venom"],"Gallstones and alcohol together account for most cases in adults."],["q-fcps-pat4-59","A 55-year-old man has painless jaundice, a palpable gallbladder and weight loss. Courvoisier's law suggests:",["Malignant obstruction of the common bile duct","Gallstone obstruction of the common bile duct","Acute cholecystitis","Hepatitis"],"A palpable non-tender gallbladder with jaundice is more likely to be caused by cancer, since a gallbladder scarred by stones cannot distend."],["q-fcps-pat4-60","Nephrotic syndrome in an adult with a 'spike and dome' appearance on silver stain is:",["Membranous nephropathy","Minimal change disease","Focal segmental glomerulosclerosis","IgA nephropathy"],"Subepithelial immune deposits with basement membrane spikes occur in membranous nephropathy, associated with anti-PLA2R antibodies."],["q-fcps-pat4-61","Haematuria one to two days after an upper respiratory infection in a young man suggests:",["IgA nephropathy","Post-streptococcal glomerulonephritis","Minimal change disease","Alport syndrome"],"IgA nephropathy follows mucosal infection within days, whereas post-streptococcal glomerulonephritis follows 1 to 3 weeks later."],["q-fcps-pat4-62","Hearing loss, haematuria and lens abnormalities in a family are characteristic of:",["Alport syndrome","Fabry disease","Thin basement membrane disease","Goodpasture syndrome"],"Alport syndrome is a defect of type IV collagen, with basket-weave basement membranes."],["q-fcps-pat4-63","Clear cell renal carcinoma is associated with loss of which gene?",["VHL","WT1","RB","NF2"],"Inactivation of VHL on chromosome 3p stabilises HIF and raises VEGF. Renal cell carcinoma can invade the renal vein."],["q-fcps-pat4-64","A thyroid nodule with calcitonin secretion and amyloid stroma occurring with pheochromocytoma suggests:",["MEN type 2A","MEN type 1","MEN type 2B","Von Hippel-Lindau"],"MEN 2A comprises medullary thyroid carcinoma, pheochromocytoma and parathyroid hyperplasia with a RET mutation."],["q-fcps-pat4-65","The classic triad of MEN type 1 consists of tumours of the parathyroid, pituitary and:",["Pancreas","Adrenal medulla","Thyroid C cells","Ovary"],"MEN 1 (Wermer syndrome) involves a menin mutation and presents with parathyroid hyperplasia, pituitary adenomas and pancreatic tumours."],["q-fcps-pat4-66","Which type of thyroid cancer tends to spread by the bloodstream and is diagnosed by capsular or vascular invasion?",["Follicular carcinoma","Papillary carcinoma","Medullary carcinoma","Anaplastic carcinoma"],"Follicular carcinoma cannot be diagnosed on FNA cytology alone, and it spreads to the lungs and bone."],["q-fcps-pat4-67","Which finding on cervical cytology indicates infection with HPV?",["Koilocytes","Clue cells","Psammoma bodies","Reed-Sternberg cells"],"Koilocytes have perinuclear halos and raisinoid nuclei."],["q-fcps-pat4-68","Codman triangle on X-ray is typical of:",["Osteosarcoma","Osteochondroma","Giant cell tumour","Osteoid osteoma"],"Periosteal elevation by an aggressive tumour produces a Codman triangle and a sunburst pattern, commonly around the knee in adolescents."],["q-fcps-pat4-69","A young boy has a lytic femoral lesion with 'onion skin' periosteal reaction and a t(11;22) translocation. The diagnosis is:",["Ewing sarcoma","Osteosarcoma","Chondrosarcoma","Osteoblastoma"],"Ewing sarcoma consists of small round blue cells with an EWS-FLI1 fusion."],["q-fcps-pat4-70","Rhomboid-shaped, weakly positively birefringent crystals in joint fluid indicate:",["Pseudogout (calcium pyrophosphate)","Gout","Septic arthritis","Haemarthrosis"],"Gout shows needle-shaped crystals with strong negative birefringence."],["q-fcps-pat4-71","Neurofibrillary tangles and amyloid plaques in the hippocampus are characteristic of:",["Alzheimer disease","Parkinson disease","Pick disease","Creutzfeldt-Jakob disease"],"Tau protein forms tangles and beta-amyloid forms plaques, with early loss of cholinergic neurons in the nucleus basalis."],["q-fcps-pat4-72","Pseudopalisading necrosis is a feature of:",["Glioblastoma","Meningioma","Medulloblastoma","Schwannoma"],"Glioblastoma is a grade 4 astrocytoma with necrosis and microvascular proliferation."],["q-fcps-pat4-73","Negri bodies are found in the neurons in:",["Rabies","Herpes encephalitis","Poliomyelitis","Tetanus"],"They are eosinophilic cytoplasmic inclusions seen in the hippocampus and Purkinje cells."],["q-fcps-pat4-74","Which skin tumour is characterised by pearly papules with rodent ulceration and palisading nuclei?",["Basal cell carcinoma","Squamous cell carcinoma","Melanoma","Keratoacanthoma"],"Basal cell carcinoma is locally invasive and rarely metastasises."],["q-fcps-pat4-75","Which prognostic factor is most important for cutaneous melanoma?",["Breslow thickness","Colour","Size of lesion","Site of lesion"],"Depth of invasion in millimetres (Breslow thickness) is the strongest predictor of metastasis."],["q-fcps-pat4-76","Pemphigus vulgaris differs from bullous pemphigoid in that it shows:",["Intraepidermal acantholysis with IgG against desmoglein","Subepidermal blisters","Antibodies against hemidesmosomes","Eosinophil-rich blisters only"],"Pemphigus has flaccid blisters, a positive Nikolsky sign and a net-like IgG pattern. Pemphigoid has tense subepidermal blisters."]];
